	agents := atAgents(t, threeSubs())
	want := strings.Join(testutil.ShortcutKeys(agents.GetShortcuts()), ",")
	if want != strings.Join([]string{"ctrl+r", openKey, closeKey, tabKey, "/", ".", "?"}, ",") {
		t.Fatalf("keys = %s, want the seven in order", want)
